NavigationStack(path: $path) {
  List(items) { item in NavigationLink(value: item.id) { ItemRow(item: item) } }
    .navigationDestination(for: Item.ID.self) { id in ItemDetail(id: id) }
}

.task(id: query) {
  do { try await Task.sleep(for: .milliseconds(300)); await model.search(query) }
  catch is CancellationError { }
}

